package nl.voetbalhub.app;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;
/** Immersive official player; no application JavaScript bridge. */
public final class YoutubePlayerView extends LinearLayout {
 private final Activity activity;private final Dialog dialog;private final WebView player;private final FrameLayout stage;private final int previousOrientation;private View custom;private WebChromeClient.CustomViewCallback callback;private boolean disposed,shown;private AlertDialog consent;
 private int dp(int n){return PremiumDesign40.dp(activity,n);}
 public YoutubePlayerView(Activity a,String id,String title,Runnable close){
  super(a);if(!id.matches("[A-Za-z0-9_-]{11}"))throw new IllegalArgumentException("Invalid video ID");activity=a;previousOrientation=a.getRequestedOrientation();setVisibility(GONE);
  dialog=new Dialog(a,android.R.style.Theme_Material_NoActionBar);dialog.setOnCancelListener(d->close.run());LinearLayout root=new LinearLayout(a);root.setOrientation(VERTICAL);root.setBackgroundColor(0xFF000000);
  LinearLayout toolbar=new LinearLayout(a);toolbar.setGravity(Gravity.CENTER_VERTICAL);toolbar.setPadding(dp(12),0,dp(8),0);
  TextView heading=PremiumDesign40.text(a,"YouTube · "+title,12,PremiumDesign40.WHITE,false);heading.setSingleLine();heading.setEllipsize(android.text.TextUtils.TruncateAt.END);toolbar.addView(heading,new LayoutParams(0,-2,1));
  TextView dismiss=PremiumDesign40.text(a,"Sluiten ×",14,PremiumDesign40.GREEN,true);dismiss.setGravity(Gravity.CENTER);dismiss.setPadding(dp(16),0,dp(8),0);dismiss.setContentDescription("Video sluiten");dismiss.setFocusable(true);dismiss.setOnClickListener(v->close.run());toolbar.addView(dismiss,new LayoutParams(-2,-1));root.addView(toolbar,new LayoutParams(-1,dp(38)));
  stage=new FrameLayout(a);root.addView(stage,new LayoutParams(-1,0,1));player=new WebView(a);player.setBackgroundColor(0xFF000000);player.setVerticalScrollBarEnabled(false);player.setHorizontalScrollBarEnabled(false);
  WebSettings s=player.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMediaPlaybackRequiresUserGesture(false);s.setSupportMultipleWindows(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
  player.setWebChromeClient(new WebChromeClient(){@Override public void onShowCustomView(View v,CustomViewCallback cb){if(disposed||custom!=null){cb.onCustomViewHidden();return;}custom=v;callback=cb;player.setVisibility(GONE);stage.addView(v,new FrameLayout.LayoutParams(-1,-1));}@Override public void onHideCustomView(){hideCustom();}});
  player.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){if(!r.isForMainFrame())return false;openSource(id);return true;}@Override public boolean shouldOverrideUrlLoading(WebView v,String url){openSource(id);return true;}});
  stage.addView(player,new FrameLayout.LayoutParams(-1,-1));TextView source=PremiumDesign40.text(a,"Deze video bekijken op YouTube ↗",12,PremiumDesign40.GREEN,true);source.setGravity(Gravity.CENTER);source.setFocusable(true);source.setOnClickListener(v->openSource(id));root.addView(source,new LayoutParams(-1,dp(38)));dialog.setContentView(root);
  post(()->{if(disposed||a.isFinishing())return;dialog.show();shown=true;Window w=dialog.getWindow();w.setLayout(-1,-1);w.addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_HARDWARE_ACCELERATED);if(android.os.Build.VERSION.SDK_INT>=30){w.setDecorFitsSystemWindows(false);WindowInsetsController c=w.getInsetsController();if(c!=null){c.hide(WindowInsets.Type.systemBars());c.setSystemBarsBehavior(WindowInsetsController.BEHAVIOR_SHOW_TRANSIENT_BARS_BY_SWIPE);}}else w.getDecorView().setSystemUiVisibility(5894);a.setRequestedOrientation(ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE);
   consent=new AlertDialog.Builder(a).setTitle("YouTube-video laden?").setMessage("YouTube ontvangt je IP-adres en apparaatgegevens en kan cookies gebruiken voor video, advertenties en meting. Toestemming geldt alleen voor deze video. Meer informatie staat in de privacyverklaring van Veldio.").setNegativeButton("Weigeren",(d,n)->close.run()).setPositiveButton("Toestaan",(d,n)->load(id)).setOnCancelListener(d->close.run()).create();consent.show();});
 }
 private void load(String id){if(disposed)return;try(java.io.InputStream in=activity.getAssets().open("youtube-player43.html")){java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){out.write(buf,0,n);if(out.size()>100000)throw new java.io.IOException("Player too large");}String origin="https://"+activity.getPackageName().toLowerCase(java.util.Locale.ROOT);String html=out.toString("UTF-8").replace("__VIDEO_ID__",id).replace("__ORIGIN__",origin);player.loadDataWithBaseURL(origin+"/",html,"text/html","UTF-8",null);}catch(Exception e){Toast.makeText(activity,"Speler niet beschikbaar. Bekijk deze video op YouTube.",Toast.LENGTH_LONG).show();}}
 private void openSource(String id){pause();try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.youtube.com/watch?v="+id)));}catch(ActivityNotFoundException e){Toast.makeText(activity,"Geen YouTube-app of browser beschikbaar",Toast.LENGTH_SHORT).show();}}
 private void hideCustom(){if(custom==null)return;stage.removeView(custom);custom=null;WebChromeClient.CustomViewCallback cb=callback;callback=null;if(cb!=null)cb.onCustomViewHidden();if(!disposed)player.setVisibility(VISIBLE);}
 public void pause(){if(disposed)return;player.evaluateJavascript("if(window.pauseVeldio)pauseVeldio()",null);player.onPause();}
 public void resume(){if(!disposed)player.onResume();}
 public void dispose(){if(disposed)return;disposed=true;if(consent!=null)consent.dismiss();hideCustom();player.stopLoading();player.onPause();stage.removeView(player);player.loadUrl("about:blank");player.destroy();dialog.dismiss();if(shown)activity.setRequestedOrientation(previousOrientation);}
}
